<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {analyzeUser,askCopilot,getSecurityAlerts,getSecurityEvents,getSecurityOverview,getSecurityProfile,getSecurityProfiles,updateSecurityAlert,type CopilotAnswer,type SecurityAlert,type SecurityEvent,type SecurityOverview,type SecurityProfile,type SecurityProfileDetail} from '@/services/business'
import {useAuthStore} from '@/stores/auth'

const auth=useAuthStore(),alerts=ref<SecurityAlert[]>([]),events=ref<SecurityEvent[]>([]),profiles=ref<SecurityProfile[]>([]),alertPage=ref(0),alertPages=ref(0),alertStatus=ref(''),eventPage=ref(0),eventPages=ref(0),profilePage=ref(0),profilePages=ref(0)
const overview=ref<SecurityOverview>({alertsToday:0,criticalOpen:0,highRiskUsers:0,deniedAccess:0,alertTrend:[],riskTrend:[],alertsByModule:[]})
const error=ref(''),notice=ref(''),selected=ref(''),copilotAlert=ref(''),question=ref('Tại sao tài khoản này được đánh dấu risk?'),answer=ref<CopilotAnswer>()
const profileDetail=ref<SecurityProfileDetail>()

async function load(){const [alertResult,eventResult,profileResult,overviewResult]=await Promise.all([getSecurityAlerts(alertStatus.value,alertPage.value),getSecurityEvents(eventPage.value),getSecurityProfiles(profilePage.value),getSecurityOverview()]);alerts.value=alertResult.items;alertPages.value=alertResult.totalPages;events.value=eventResult.items;eventPages.value=eventResult.totalPages;profiles.value=profileResult.items;profilePages.value=profileResult.totalPages;overview.value=overviewResult}
async function filterAlerts(){alertPage.value=0;await load()}
async function moveAlerts(page:number){alertPage.value=page;await load()}
async function moveEvents(page:number){eventPage.value=page;await load()}
async function moveProfiles(page:number){profilePage.value=page;await load()}
async function review(alert:SecurityAlert,status:string){try{await updateSecurityAlert(alert.id,status,status==='FALSE_POSITIVE'?'Marked as false positive by investigator':'Reviewed in Trung tâm an ninh AI');await load()}catch{error.value='Không thể cập nhật cảnh báo.'}}
async function analyze(){if(!selected.value)return;const end=new Date(),start=new Date(end.getTime()-3600000);try{const result=await analyzeUser({userId:selected.value,windowStart:start.toISOString(),windowEnd:end.toISOString()});notice.value=`Đã đánh giá: ${result.severity} (${Math.round(result.riskScore)}/100) · baseline ${result.baselineScope} (${result.baselineSampleSize} mẫu).`;await load()}catch{error.value='Không thể phân tích. Cần model đã train/activate và dữ liệu hoạt động trong 1 giờ gần nhất.'}}
async function ask(){if(!copilotAlert.value){error.value='Hãy chọn một cảnh báo để AI có bằng chứng phân tích.';return}if(!question.value.trim()){error.value='Hãy nhập câu hỏi cho trợ lý AI.';return}error.value='';answer.value=undefined;try{answer.value=await askCopilot(copilotAlert.value,question.value)}catch{error.value='Trợ lý AI chưa hoạt động: quản trị viên cần bật LLM_ENABLED và cấu hình LLM_MODEL cùng endpoint tương thích OpenAI.'}}
async function inspectProfile(id:string){try{profileDetail.value=await getSecurityProfile(id)}catch{error.value='Không thể tải hồ sơ an ninh người dùng.'}}
function height(value:number,values:Array<{value:number}>){const max=Math.max(1,...values.map(point=>point.value));return `${Math.max(3,Math.round(value/max*100))}%`}
onMounted(async()=>{try{await load()}catch{error.value='Không thể tải Trung tâm an ninh AI.'}})
</script>

<template>
  <section class="security-console">
    <div class="overflow-hidden rounded-2xl border border-slate-800 bg-gradient-to-br from-slate-900 via-slate-900 to-cyan-950/50 p-5 sm:p-7">
      <div class="flex flex-wrap items-end justify-between gap-5"><div><div class="mb-3 inline-flex items-center gap-2 rounded-full border border-cyan-400/20 bg-cyan-400/10 px-3 py-1 text-xs font-semibold text-cyan-300"><span class="h-1.5 w-1.5 rounded-full bg-emerald-400"></span>Giám sát theo thời gian thực</div><h2 class="text-2xl font-bold tracking-tight text-white sm:text-3xl">Trung tâm an ninh AI</h2><p class="mt-2 max-w-2xl text-sm leading-6 text-slate-400">Theo dõi bất thường, điều tra cảnh báo và phân tích hành vi người dùng từ dữ liệu hệ thống.</p></div><div v-if="auth.hasPermission('security.analyze')" class="grid w-full gap-2 sm:w-auto sm:grid-cols-[15rem_auto]"><select v-model="selected" class="rounded-xl border border-slate-700 bg-slate-950 px-3 py-3 text-sm text-slate-100"><option value="">Chọn người dùng</option><option v-for="p in profiles" :key="p.userId" :value="p.userId">{{p.username}}</option></select><button :disabled="!selected" class="rounded-xl bg-cyan-600 px-5 py-3 text-sm font-semibold text-white hover:bg-cyan-500 disabled:cursor-not-allowed disabled:opacity-40" @click="analyze">Phân tích 1 giờ</button></div></div>
    </div>
    <p v-if="error" class="mt-5 rounded-lg bg-red-50 p-4 text-red-800">{{error}}</p><p v-if="notice" class="mt-5 rounded-lg bg-emerald-50 p-4 text-emerald-800">{{notice}}</p>
    <div class="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div class="metric-card"><div class="metric-icon bg-cyan-400/10 text-cyan-300">⌁</div><div><p class="metric-label">Cảnh báo hôm nay</p><p class="metric-value">{{overview.alertsToday}}</p></div></div><div class="metric-card"><div class="metric-icon bg-red-400/10 text-red-300">!</div><div><p class="metric-label">Nghiêm trọng chưa xử lý</p><p class="metric-value text-red-300">{{overview.criticalOpen}}</p></div></div><div class="metric-card"><div class="metric-icon bg-amber-400/10 text-amber-300">△</div><div><p class="metric-label">Người dùng rủi ro cao</p><p class="metric-value text-amber-300">{{overview.highRiskUsers}}</p></div></div><div class="metric-card"><div class="metric-icon bg-violet-400/10 text-violet-300">⊘</div><div><p class="metric-label">Truy cập bị từ chối · 30 ngày</p><p class="metric-value">{{overview.deniedAccess}}</p></div></div></div>
    <div class="mt-6 grid gap-4 lg:grid-cols-3"><div class="rounded-xl border bg-white p-5"><h3 class="font-bold">Xu hướng cảnh báo · 30 ngày</h3><div class="mt-4 flex h-32 items-end gap-1" aria-label="Biểu đồ số alert theo ngày"><div v-for="point in overview.alertTrend" :key="point.date" class="min-w-1 flex-1 rounded-t bg-cyan-600" :style="{height:height(point.value,overview.alertTrend)}" :title="`${point.date}: ${point.value}`"></div></div></div><div class="rounded-xl border bg-white p-5"><h3 class="font-bold">Điểm rủi ro trung bình</h3><div class="mt-4 flex h-32 items-end gap-1" aria-label="Biểu đồ risk score theo ngày"><div v-for="point in overview.riskTrend" :key="point.date" class="min-w-1 flex-1 rounded-t bg-amber-500" :style="{height:height(point.value,overview.riskTrend)}" :title="`${point.date}: ${point.value.toFixed(1)}`"></div></div></div><div class="rounded-xl border bg-white p-5"><h3 class="font-bold">Cảnh báo theo phân hệ</h3><div class="mt-3 divide-y"><p v-for="item in overview.alertsByModule" :key="item.module" class="flex justify-between py-2 text-sm"><span>{{item.module}}</span><b>{{item.count}}</b></p><p v-if="!overview.alertsByModule.length" class="py-4 text-sm text-slate-400">Chưa có cảnh báo trong kỳ.</p></div></div></div>
    <div class="mt-6 grid gap-4 lg:grid-cols-[18rem_1fr]"><div class="rounded-xl border bg-white p-4"><h3 class="font-bold">Hồ sơ an ninh người dùng</h3><div class="mt-3 divide-y"><button v-for="profile in profiles.slice(0,20)" :key="profile.userId" class="flex w-full justify-between py-2 text-left text-sm hover:text-cyan-700" @click="inspectProfile(profile.userId)"><span>{{profile.username}}</span><span>{{profile.denied30d}} lượt bị từ chối</span></button></div></div><div class="rounded-xl border bg-white p-4"><h3 class="font-bold">Chi tiết hồ sơ</h3><p v-if="!profileDetail" class="mt-3 text-sm text-slate-400">Chọn một người dùng để xem hành vi bình thường, hoạt động gần đây, rủi ro và dòng thời gian.</p><template v-else><div class="mt-3 grid gap-3 sm:grid-cols-3"><p class="rounded-lg bg-slate-50 p-3 text-sm">Rủi ro hiện tại<br><b class="text-xl">{{profileDetail.currentRisk===undefined?'—':Math.round(profileDetail.currentRisk)}}</b></p><p class="rounded-lg bg-slate-50 p-3 text-sm">Lượt đánh giá rủi ro<br><b class="text-xl">{{profileDetail.riskHistory.length}}</b></p><p class="rounded-lg bg-slate-50 p-3 text-sm">Cảnh báo<br><b class="text-xl">{{profileDetail.alertHistory.length}}</b></p></div><details class="mt-3 rounded-lg border p-3 text-sm"><summary class="cursor-pointer font-semibold">Hành vi bình thường / đường cơ sở</summary><pre class="mt-2 overflow-auto text-xs">{{profileDetail.normalBehavior}}</pre></details><details class="mt-3 rounded-lg border p-3 text-sm"><summary class="cursor-pointer font-semibold">Hành vi gần đây</summary><pre class="mt-2 overflow-auto text-xs">{{profileDetail.recentBehavior}}</pre></details><div class="mt-3 max-h-56 overflow-auto divide-y"><p v-for="activity in profileDetail.activityTimeline" :key="activity.id" class="grid gap-2 py-2 text-xs sm:grid-cols-[10rem_1fr_8rem]"><span>{{new Date(activity.occurredAt).toLocaleString()}}</span><span>{{activity.action}} · {{activity.module}}</span><b>{{activity.result}}</b></p></div></template></div></div>
    <div class="mt-3 flex items-center justify-end gap-3 text-sm"><span>Trang hồ sơ {{profilePages?profilePage+1:0}} / {{profilePages}}</span><button :disabled="profilePage===0" class="rounded border bg-white px-3 py-2 disabled:opacity-40" @click="moveProfiles(profilePage-1)">Trước</button><button :disabled="profilePage+1>=profilePages" class="rounded border bg-white px-3 py-2 disabled:opacity-40" @click="moveProfiles(profilePage+1)">Sau</button></div>
    <div class="mt-6 flex flex-wrap items-center justify-between gap-3"><select v-model="alertStatus" class="rounded-lg border bg-white p-2 text-sm" @change="filterAlerts"><option value="">Tất cả trạng thái cảnh báo</option><option value="OPEN">Chưa xử lý</option><option value="INVESTIGATING">Đang điều tra</option><option value="RESOLVED">Đã giải quyết</option><option value="FALSE_POSITIVE">Không phải rủi ro</option></select><div class="flex items-center gap-3 text-sm"><button :disabled="alertPage===0" class="rounded border bg-white px-3 py-2 disabled:opacity-40" @click="moveAlerts(alertPage-1)">Trước</button><span>Trang {{alertPages?alertPage+1:0}} / {{alertPages}}</span><button :disabled="alertPage+1>=alertPages" class="rounded border bg-white px-3 py-2 disabled:opacity-40" @click="moveAlerts(alertPage+1)">Sau</button></div></div>
    <div class="mt-3 overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-4">Người dùng</th><th class="p-4">Mức độ</th><th class="p-4">Rủi ro</th><th class="p-4">Lý do</th><th class="p-4">Trạng thái / xử lý</th></tr></thead><tbody class="divide-y"><tr v-for="a in alerts" :key="a.id"><td class="p-4">{{a.username}}</td><td class="p-4 font-bold"><StatusBadge :value="a.severity" /></td><td class="p-4">{{Math.round(a.riskScore)}}/100</td><td class="p-4 font-mono text-xs">{{a.reasons}}</td><td class="p-4"><StatusBadge :value="a.status" /><template v-if="auth.hasPermission('security.alert.review')&&!['RESOLVED','FALSE_POSITIVE'].includes(a.status)"><button class="mr-2 text-cyan-700" @click="review(a,a.status==='OPEN'?'INVESTIGATING':'RESOLVED')">{{a.status==='OPEN'?'Điều tra':'Giải quyết'}}</button><button class="text-slate-500" @click="review(a,'FALSE_POSITIVE')">Không phải rủi ro</button></template></td></tr><tr v-if="!alerts.length"><td colspan="5" class="p-8 text-center text-slate-400">Không có cảnh báo phù hợp.</td></tr></tbody></table></div>
    <div v-if="auth.hasPermission('security.copilot')" class="mt-6 rounded-xl border bg-white p-5"><div class="flex flex-wrap items-start justify-between gap-3"><div><h3 class="font-bold">Trợ lý an ninh AI</h3><p class="mt-1 text-sm text-slate-500">Chọn một cảnh báo để AI giải thích từ bằng chứng đã ghi nhận. Trợ lý chỉ đọc và không tự thay đổi trạng thái.</p></div><span class="rounded-full border border-cyan-400/20 bg-cyan-400/10 px-3 py-1 text-xs text-cyan-200">Có dẫn chứng · Chỉ đọc</span></div><div class="mt-4 grid gap-3 md:grid-cols-[16rem_1fr_auto]"><select v-model="copilotAlert" class="rounded-lg border p-3"><option value="">Chọn cảnh báo cần phân tích</option><option v-for="a in alerts" :key="a.id" :value="a.id">{{a.username}} · {{a.severity}}</option></select><input v-model="question" maxlength="2000" class="rounded-lg border p-3" placeholder="Ví dụ: Vì sao tài khoản này có rủi ro cao?"><button :disabled="!copilotAlert || !question.trim()" class="rounded-lg bg-cyan-600 px-4 font-semibold text-white hover:bg-cyan-500 disabled:cursor-not-allowed disabled:opacity-40" @click="ask">Hỏi AI</button></div><p v-if="!alerts.length" class="mt-3 text-xs text-amber-200">Chưa có cảnh báo để làm nguồn bằng chứng. Hãy chạy phân tích người dùng trước.</p><div v-if="answer" class="mt-4 whitespace-pre-wrap rounded-lg bg-slate-50 p-4">{{answer.answer}}<p class="mt-3 text-xs text-slate-500">Bằng chứng: {{answer.evidence.map(e=>e.id).join(', ')}} · {{answer.model}}</p></div></div>
    <div class="mt-6 rounded-xl border bg-white p-5"><div class="flex items-center justify-between gap-3"><h3 class="font-bold">Sự kiện an ninh gần đây</h3><div class="flex items-center gap-2 text-sm"><button :disabled="eventPage===0" class="rounded border px-3 py-2 disabled:opacity-40" @click="moveEvents(eventPage-1)">Trước</button><span>{{eventPages?eventPage+1:0}} / {{eventPages}}</span><button :disabled="eventPage+1>=eventPages" class="rounded border px-3 py-2 disabled:opacity-40" @click="moveEvents(eventPage+1)">Sau</button></div></div><div class="mt-3 divide-y"><p v-for="event in events" :key="event.id" class="grid gap-2 py-3 text-sm md:grid-cols-[10rem_8rem_1fr]"><b>{{event.severity}}</b><span>{{event.eventType}}</span><span>{{new Date(event.occurredAt).toLocaleString()}} · {{event.module}}</span></p><p v-if="!events.length" class="py-4 text-slate-400">Không có security event.</p></div></div>
  </section>
</template>

<style scoped>
.security-console { color: rgb(226 232 240); }
.security-console :deep(.bg-white) { background-color: rgb(15 23 42); }
.security-console :deep(.bg-slate-50) { background-color: rgb(2 6 23 / .72); }
.security-console :deep(.border) { border-color: rgb(51 65 85); }
.security-console :deep(.divide-y > :not([hidden]) ~ :not([hidden])) { border-color: rgb(51 65 85); }
.security-console :deep(.text-slate-500) { color: rgb(148 163 184); }
.security-console :deep(.text-slate-400) { color: rgb(148 163 184); }
.security-console :deep(.text-cyan-700) { color: rgb(103 232 249); }
.security-console :deep(input),
.security-console :deep(select) {
  border-color: rgb(51 65 85);
  background-color: rgb(2 6 23);
  color: rgb(226 232 240);
}
.security-console :deep(option) { background-color: rgb(15 23 42); color: rgb(226 232 240); }
.security-console :deep(table thead) { background-color: rgb(2 6 23 / .72); color: rgb(203 213 225); }
.security-console :deep(table tbody tr:hover) { background-color: rgb(30 41 59 / .65); }
.security-console :deep(pre) { color: rgb(203 213 225); }
.metric-card {
  display: flex;
  min-height: 8rem;
  align-items: center;
  gap: 1rem;
  border: 1px solid rgb(30 41 59);
  border-radius: 1rem;
  background: linear-gradient(145deg, rgb(15 23 42), rgb(15 23 42 / .72));
  padding: 1.25rem;
}
.metric-icon { display: grid; height: 2.75rem; width: 2.75rem; flex: none; place-items: center; border-radius: .75rem; font-size: 1.25rem; font-weight: 800; }
.metric-label { color: rgb(148 163 184); font-size: .8125rem; line-height: 1.25rem; }
.metric-value { margin-top: .25rem; color: white; font-size: 1.875rem; line-height: 2.25rem; font-weight: 750; }
</style>
